-- ugui runtime: generated by tools/importers/unity_ui (screens converted from Unity uGUI / UI.Windows).
-- Scales each screen's canvas like Unity's CanvasScaler, applies the safe area to `.u-safe` containers,
-- loads the imported fonts and routes clicks to ui/logic/<screen>.lua (on.click[id] or click(id, element)).
-- Regenerated on every import: put game logic into ui/logic/*.lua, not here.
local M = {}
local cfg = require('ugui.config')
local docs, logic = {}, {}

for _, f in ipairs(cfg.fonts or {}) do rmlui:LoadFontFace(f) end

local function attr(el, name, default)
    local v = el:GetAttribute(name)
    if v == nil or v == '' then return default end
    return v
end

local function scaleOf(vw, vh, s)
    if s.mode ~= 1 then return 1 end
    if s.screenMatch == 1 then return math.min(vw / s.w, vh / s.h) end
    if s.screenMatch == 2 then return math.max(vw / s.w, vh / s.h) end
    local lw, lh = math.log(vw / s.w, 2), math.log(vh / s.h, 2)
    return 2 ^ (lw + (lh - lw) * s.match)
end

function M.layout(doc)
    local canvas = doc:GetElementById('ugui-canvas')
    if not canvas then return end
    local ctx = doc.context
    local r = ctx.dp_ratio
    if not r or r <= 0 then r = 1 end
    local vw, vh = ctx.dimensions.x / r, ctx.dimensions.y / r
    local s = {mode = tonumber(attr(canvas, 'u-scale-mode', '1')), w = tonumber(attr(canvas, 'u-ref-w', '1920')),
               h = tonumber(attr(canvas, 'u-ref-h', '1080')), match = tonumber(attr(canvas, 'u-match', '0')),
               screenMatch = tonumber(attr(canvas, 'u-screen-match', '0'))}
    local k = scaleOf(vw, vh, s)
    canvas.style.width = string.format('%.2fdp', vw / k)
    canvas.style.height = string.format('%.2fdp', vh / k)
    canvas.style.transform = string.format('scale(%.5f)', k)
    local safe = game.safeArea()
    for _, z in ipairs(doc:QuerySelectorAll('.u-safe')) do
        z.style.left = string.format('%.2fdp', safe.left / k)
        z.style.right = string.format('%.2fdp', safe.right / k)
        z.style.top = string.format('%.2fdp', safe.top / k)
        z.style.bottom = string.format('%.2fdp', safe.bottom / k)
        z.style['margin-left'] = '0dp'; z.style['margin-right'] = '0dp'
        z.style['margin-top'] = '0dp'; z.style['margin-bottom'] = '0dp'
    end
end

function M.logic(screen)
    if logic[screen] == nil then
        local ok, mod = pcall(require, 'logic.' .. screen)
        logic[screen] = ok and type(mod) == 'table' and mod or false
    end
    return logic[screen] or nil
end

function M.mount(doc)
    docs[#docs + 1] = doc
    M.layout(doc)
    local name = attr(doc:GetElementById('ugui-canvas'), 'u-screen', '')
    local l = M.logic(name)
    if l and l.mount then l.mount(doc) end
end

function M.click(element, event)
    local canvas = element.owner_document:GetElementById('ugui-canvas')
    local l = M.logic(canvas and attr(canvas, 'u-screen', '') or '')
    if not l then return end
    if l.on and l.on[element.id] then return l.on[element.id](element, event) end
    if l.click then return l.click(element.id, element, event) end
end

-- Image.fillAmount of a horizontal / vertical fill (u-fill-method): the element's width / height in % of
-- its authored size (u-fill-size, set on the first call).
function M.fill(el, amount)
    amount = math.max(0, math.min(1, amount))
    local m = attr(el, 'u-fill-method', 'horizontal')
    local prop = m == 'vertical' and 'height' or 'width'
    local full = tonumber(attr(el, 'u-fill-size', ''))
    if not full then
        full = m == 'vertical' and el.offset_height or el.offset_width
        el:SetAttribute('u-fill-size', tostring(full))
    end
    el:SetAttribute('u-fill', tostring(amount))
    el.style[prop] = string.format('%.2fpx', full * amount)
end

-- UI.Windows WindowComponent.Show / Hide: the authored display comes back from u-display.
function M.show(el, on)
    el.style.display = on == false and 'none' or attr(el, 'u-display', 'block')
end

game.on('resize', function() for _, d in ipairs(docs) do M.layout(d) end end)
return M
